/**
 * Rick Autumn Falling Leaves (Vanilla JS Animation)
 * 
 * 60 FPS GPU-accelerated falling autumn leaves simulation.
 * Pure JS, zero external dependencies, pointer-events: none.
 */
(function() {
    'use strict';

    if (window.rickAutumnLeavesInitialized) {
        return;
    }
    window.rickAutumnLeavesInitialized = true;

    // Respect user motion preferences
    if (window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
        return;
    }

    var leafSvgs = [
        // 1. Esdoornblad (Maple leaf)
        '<svg viewBox="0 0 100 100" fill="currentColor"><path d="M50 5 C52 18 58 22 66 18 C65 24 69 26 76 25 C72 32 75 36 84 37 C77 43 78 48 83 55 C74 56 72 61 73 70 C65 67 61 70 58 78 C54 74 52 75 51 86 L49 86 C48 75 46 74 42 78 C39 70 35 67 27 70 C28 61 26 56 17 55 C22 48 23 43 16 37 C25 36 28 32 24 25 C31 26 35 24 34 18 C42 22 48 18 50 5 Z M49 86 L50 96 L52 86 Z"/></svg>',
        // 2. Eikenblad (Oak leaf)
        '<svg viewBox="0 0 100 100" fill="currentColor"><path d="M50 5 C56 10 65 14 62 24 C72 26 76 35 69 44 C78 48 78 60 67 67 C72 73 68 81 58 84 C56 87 53 90 51 96 L49 96 C47 90 44 87 42 84 C32 81 28 73 33 67 C22 60 22 48 31 44 C24 35 28 26 38 24 C35 14 44 10 50 5 Z"/></svg>',
        // 3. Beukenblad (Beech leaf)
        '<svg viewBox="0 0 100 100" fill="currentColor"><path d="M50 5 C68 20 80 45 74 72 C70 82 58 88 52 92 L50 98 L48 92 C42 88 30 82 26 72 C20 45 32 20 50 5 Z"/></svg>'
    ];

    var autumnColors = [
        '#dc2626', // Rood
        '#ea580c', // Vurig oranje
        '#f59e0b', // Warm goudgeel
        '#d97706', // Amber
        '#b45309', // Brons
        '#92400e', // Kastanjebruin
        '#78350f'  // Diep kaneel
    ];

    function initLeaves() {
        var cfg = window.rickAutumnConfig || {};
        var maxLeaves = parseInt(cfg.leafCount, 10) || 32;
        var followMouse = cfg.followMouse !== false;

        // Container element
        var container = document.createElement('div');
        container.id = 'rick-autumn-leaves-container';
        container.setAttribute('aria-hidden', 'true');
        container.style.cssText = 'position:fixed;top:0;left:0;width:100vw;height:100vh;overflow:hidden;pointer-events:none;z-index:99998;';
        document.body.appendChild(container);

        var width = window.innerWidth;
        var height = window.innerHeight;
        var mouseX = -1000;
        var mouseY = -1000;

        if (followMouse) {
            window.addEventListener('mousemove', function(e) {
                mouseX = e.clientX;
                mouseY = e.clientY;
            }, { passive: true });
        }

        window.addEventListener('resize', function() {
            width = window.innerWidth;
            height = window.innerHeight;
        }, { passive: true });

        var leaves = [];

        function Leaf() {
            this.el = document.createElement('div');
            this.el.className = 'rick-autumn-leaf';
            this.el.style.cssText = 'position:absolute;top:0;left:0;will-change:transform;pointer-events:none;filter:drop-shadow(0 2px 4px rgba(0,0,0,0.25));';
            
            var svgIdx = Math.floor(Math.random() * leafSvgs.length);
            var color = autumnColors[Math.floor(Math.random() * autumnColors.length)];
            
            this.el.innerHTML = leafSvgs[svgIdx];
            this.el.style.color = color;
            
            this.reset(true);
            container.appendChild(this.el);
        }

        Leaf.prototype.reset = function(initial) {
            this.size = 20 + Math.random() * 20; // 20px - 40px
            this.el.style.width = this.size + 'px';
            this.el.style.height = this.size + 'px';
            this.el.style.opacity = 0.82 + Math.random() * 0.18;

            this.x = Math.random() * width;
            this.y = initial ? (Math.random() * height) : (-50 - Math.random() * 60);

            this.speedY = 1.0 + Math.random() * 1.8;
            this.speedX = (Math.random() - 0.5) * 1.2;

            this.swaySpeed = 0.015 + Math.random() * 0.02;
            this.swayAmp = 1.2 + Math.random() * 2.2;
            this.swayPhase = Math.random() * Math.PI * 2;

            this.rotX = Math.random() * 360;
            this.rotY = Math.random() * 360;
            this.rotZ = Math.random() * 360;

            this.rotSpeedX = (Math.random() - 0.5) * 2.0;
            this.rotSpeedY = (Math.random() - 0.5) * 2.5;
            this.rotSpeedZ = (Math.random() - 0.5) * 1.5;
        };

        Leaf.prototype.update = function(time) {
            this.y += this.speedY;
            this.x += Math.sin(time * this.swaySpeed + this.swayPhase) * this.swayAmp + this.speedX;

            this.rotX += this.rotSpeedX;
            this.rotY += this.rotSpeedY;
            this.rotZ += this.rotSpeedZ;

            // Muisinteractie: subtiel wegwapperen bij bewegende muis
            if (followMouse && mouseX > 0) {
                var dx = this.x - mouseX;
                var dy = this.y - mouseY;
                var dist = Math.sqrt(dx * dx + dy * dy);
                if (dist < 120 && dist > 0) {
                    var force = (120 - dist) / 120;
                    this.x += (dx / dist) * force * 3.5;
                    this.y += (dy / dist) * force * 2.5;
                    this.rotZ += force * 8;
                }
            }

            // Buiten scherm gevallen? Reset naar boven
            if (this.y > height + 40) {
                this.reset(false);
            }
            if (this.x < -60) {
                this.x = width + 40;
            } else if (this.x > width + 60) {
                this.x = -40;
            }

            this.el.style.transform = 'translate3d(' + this.x.toFixed(1) + 'px,' + this.y.toFixed(1) + 'px,0) rotateX(' + this.rotX.toFixed(1) + 'deg) rotateY(' + this.rotY.toFixed(1) + 'deg) rotateZ(' + this.rotZ.toFixed(1) + 'deg)';
        };

        for (var i = 0; i < maxLeaves; i++) {
            leaves.push(new Leaf());
        }

        var frame = 0;
        function animate() {
            frame++;
            for (var i = 0; i < leaves.length; i++) {
                leaves[i].update(frame);
            }
            requestAnimationFrame(animate);
        }

        requestAnimationFrame(animate);
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initLeaves);
    } else {
        initLeaves();
    }
})();
